arguments.query:
query VideoRunContext {
 games(first: 40, offset: 0) { nodes { id name slug } pageInfo { total first offset hasMore nextOffset } }
 videos(first: 80, offset: 0) { nodes { id title slug status duration publishedAt game { id name slug } playlists { id title slug } } pageInfo { total first offset hasMore nextOffset } }
 playlists(first: 80, offset: 0) { nodes { id title slug game { id name slug } } pageInfo { total first offset hasMore nextOffset } }
}
